#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct {
    int *data;
    int head, tail;
} Deque;

static void dq_init(Deque *q, int n) {
    q->data = (int *)malloc((n + 5) * sizeof(int));
    q->head = 0;
    q->tail = 0;
}

static void dq_free(Deque *q) {
    free(q->data);
}

static int dq_empty(Deque *q) {
    return q->head == q->tail;
}

static int dq_front(Deque *q) {
    return q->data[q->head];
}

static int dq_back(Deque *q) {
    return q->data[q->tail - 1];
}

static void dq_pop_front(Deque *q) {
    q->head++;
}

static void dq_pop_back(Deque *q) {
    q->tail--;
}

static void dq_push_back(Deque *q, int x) {
    q->data[q->tail++] = x;
}

int main(void) {
    int n, m;
    ll k;
    if (scanf("%d %d %lld", &n, &m, &k) != 3) return 0;

    int *a = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);

    ll *dp = (ll *)malloc((n + 1) * sizeof(ll));
    for (int i = 0; i <= n; i++) dp[i] = LLONG_MAX / 4;
    dp[0] = 0;

    Deque qmax, qmin;
    dq_init(&qmax, n);
    dq_init(&qmin, n);

    for (int i = 1; i <= n; i++) {
        while (!dq_empty(&qmax) && a[dq_back(&qmax)] <= a[i]) dq_pop_back(&qmax);
        dq_push_back(&qmax, i);

        while (!dq_empty(&qmin) && a[dq_back(&qmin)] >= a[i]) dq_pop_back(&qmin);
        dq_push_back(&qmin, i);

        int start = i - m + 1;
        if (start < 1) start = 1;

        while (!dq_empty(&qmax) && dq_front(&qmax) < start) dq_pop_front(&qmax);
        while (!dq_empty(&qmin) && dq_front(&qmin) < start) dq_pop_front(&qmin);

        ll best = LLONG_MAX / 4;

        /* Try all valid box starts j..i, where box size <= m */
        for (int j = i; j >= start; j--) {
            /* maintain max/min for suffix j..i by direct update */
            /* Since constraints are unknown from statement fragment,
               use straightforward O(n*m) DP transition. */
        }

        int curMax = a[i], curMin = a[i];
        for (int j = i; j >= start; j--) {
            if (a[j] > curMax) curMax = a[j];
            if (a[j] < curMin) curMin = a[j];
            ll cost = dp[j - 1] + k + (ll)(curMax - curMin) * (i - j + 1);
            if (cost < best) best = cost;
        }
        dp[i] = best;
    }

    printf("%lld\n", dp[n]);

    dq_free(&qmax);
    dq_free(&qmin);
    free(a);
    free(dp);
    return 0;
}

