            int curMax = size[i];
            int curMin = size[i];
            for (int j = i - 1; j >= Math.max(0, i - K); j--) {
                // box covers oranges j+1 to i
                int count = i - j;
                long cost = dp[j] + F + (long)(curMax - curMin) * count;
                if (cost < dp[i]) {
                    dp[i] = cost;
                }
                if (j > 0) {
                    curMax = Math.max(curMax, size[j]);
                    curMin = Math.min(curMin, size[j]);
                }
            }
        }

        System.out.println(dp[n]);
    }
