import java.io.*;
import java.util.*;

/*
Assumed full problem (standard "Packing Oranges" style):
- There are N oranges in a fixed order.
- Orange i has size a[i].
- A box can contain at most M oranges.
- If a consecutive segment of oranges is packed into one box, its cost is:
      K + (max size in the box - min size in the box) * number of oranges in the box
- Find the minimum total cost to pack all oranges.

Input format assumed:
N M K
a1 a2 ... aN

Output:
minimum total cost

This solution uses DP:
dp[i] = minimum cost to pack first i oranges
Transition:
dp[i] = min over j in [max(1, i-M+1) .. i]:
        dp[j-1] + K + (max(a[j..i]) - min(a[j..i])) * (i-j+1)

Time: O(N*M)
Space: O(N)

This is the natural solution when only the above information is provided.
*/
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        long K = fs.nextLong();

        long[] a = new long[N + 1];
        for (int i = 1; i <= N; i++) a[i] = fs.nextLong();

        long[] dp = new long[N + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 4);
        dp[0] = 0;

        for (int i = 1; i <= N; i++) {
            long mn = a[i], mx = a[i];
            for (int len = 1; len <= M && i - len + 1 >= 1; len++) {
                int j = i - len + 1;
                mn = Math.min(mn, a[j]);
                mx = Math.max(mx, a[j]);
                long cost = K + (mx - mn) * len;
                dp[i] = Math.min(dp[i], dp[j - 1] + cost);
            }
        }

        System.out.println(dp[N]);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
